const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeWinnipeg = ee.Geometry.Polygon([
    [[-98.5, 53.0], [-96.0, 53.0], [-96.0, 50.0], [-98.5, 50.0], [-98.5, 53.0]]
  ]);

  const date1 = '2021-05-07';
  const date2 = '2021-05-19';

  // 2. Data Acquisition - Sentinel-2 with cloud masking
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                  .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function getIceArea(date) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(lakeWinnipeg)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .map(maskS2clouds);

    const size = collection.size().getInfo();
    if (size === 0) return {area: null, pixels: 0, images: 0};

    const image = collection.mosaic();

    // Calculate NDSI for ice detection: (B3 - B11) / (B3 + B11)
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');

    // Ice mask: NDSI > 0.4 (common threshold for snow/ice)
    const iceMask = ndsi.gt(0.4);

    // Calculate ice area in square meters
    const iceArea = iceMask.multiply(ee.Image.pixelArea());

    // Get pixel count and total area
    const stats = iceArea.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeWinnipeg,
      scale: 300,
      maxPixels: 1e9
    });

    const area = stats.get('NDSI').getInfo();
    const pixelCount = iceMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeWinnipeg,
      scale: 300,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    return {area: area, pixels: pixelCount, images: size};
  }

  // 3. Get ice areas for both dates
  const ice1 = getIceArea(date1);
  const ice2 = getIceArea(date2);

  // 4. Check for empty collections
  if (ice1.images === 0 || ice2.images === 0) {
    print(`${date1} Images: ${ice1.images}, ${date2} Images: ${ice2.images}`);
    print("<answer>C1</answer>");
    return;
  }

  // 5. Check for no valid pixels
  if (ice1.pixels === 0 || ice2.pixels === 0) {
    print(`${date1} Pixels: ${ice1.pixels}, ${date2} Pixels: ${ice2.pixels}`);
    print("<answer>C2</answer>");
    return;
  }

  // 6. Validate calculations
  if (ice1.area === null || ice2.area === null || 
      isNaN(ice1.area) || isNaN(ice2.area)) {
    print("Calculation failed - null/NaN results");
    print("<answer>C3</answer>");
    return;
  }

  // 7. Print results and determine answer
  print(`${date1}: ${(ice1.area/1e6).toFixed(1)} km² (Pixels: ${ice1.pixels})`);
  print(`${date2}: ${(ice2.area/1e6).toFixed(1)} km² (Pixels: ${ice2.pixels})`);
  print(`Change: ${((ice2.area - ice1.area)/1e6).toFixed(1)} km²`);

  // 8. Final answer based on ice extent change
  if (ice2.area < ice1.area) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
